import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using the Quickselect algorithm.
    Average time complexity is O(n), worst-case O(n^2).
    """
    if k < 1 or k > len(nums):
        raise ValueError("k is out of bounds of the list length.")

    def partition(left: int, right: int, pivot_index: int) -> int:
        pivot_value = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:  # Looking for the k-th largest
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        nums[store_index], nums[right] = nums[right], nums[store_index]
        return store_index

    def quickselect(left: int, right: int, k: int) -> int:
        if left == right:
            return nums[left]

        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)

        if k == pivot_index:
            return nums[k]
        elif k < pivot_index:
            return quickselect(left, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, right, k)

    return quickselect(0, len(nums) - 1, k - 1)

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using the Median of Medians algorithm.
    The average time complexity is O(n), and the worst-case time complexity is O(n).
    """
    if k < 1 or k > len(nums):
        raise ValueError("k is out of bounds of the list length.")

    def median_of_medians(lst: list[int]) -> int:
        if len(lst) < 10:
            return sorted(lst)[len(lst) // 2]  # Use sort for small size for simplicity
        medians = []
        for i in range(0, len(lst), 5):
            group = lst[i:i+5]
            medians.append(sorted(group)[len(group) // 2])
        return median_of_medians(medians)

    def partition(lst: list[int], pivot: int) -> tuple[list[int], list[int]]:
        left = []
        right = []
        for num in lst:
            if num > pivot:  # Looking for the k-th largest
                left.append(num)
            elif num < pivot:
                right.append(num)
        return left, right

    pivot = median_of_medians(nums)
    left, right = partition(nums, pivot)

    if k <= len(left):
        return kth_largest(left, k)
    elif k > len(nums) - len(right):
        return kth_largest(right, k - (len(nums) - len(right)))
    else:
        return pivot

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using a modified binary search approach.
    Time complexity is O(n) on average, O(n log n) in the worst case, depending on the pivot selection.
    """
    if k < 1 or k > len(nums):
        raise ValueError("k is out of bounds of the list length.")

    def count_greater_equal(pivot: int) -> int:
        """Count how many numbers are greater than or equal to the pivot."""
        return sum(num >= pivot for num in nums)

    left, right = min(nums), max(nums)

    while left < right:
        mid = (left + right) // 2
        if count_greater_equal(mid) < k:
            right = mid
        else:
            left = mid + 1

    return left if count_greater_equal(left) >= k else left - 1
